PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE IT_Students_2024_2028 (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL UNIQUE,
    register_no TEXT NOT NULL UNIQUE,
    student_name TEXT NOT NULL,
    year INTEGER NOT NULL,
    section TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    auth_user_id TEXT
, mentor_email TEXT);
CREATE TABLE IT_Students_2025_2029 (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL UNIQUE,
    register_no TEXT NOT NULL UNIQUE,
    student_name TEXT NOT NULL,
    year INTEGER NOT NULL,
    section TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    auth_user_id TEXT
, mentor_email TEXT);
CREATE TABLE IT_Attendance_2024_2028 (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    attendance_id TEXT NOT NULL,
    register_no TEXT NOT NULL,
    section TEXT NOT NULL,
    attendance_date TEXT NOT NULL,
    period INTEGER NOT NULL,
    subject_code TEXT NOT NULL,
    subject_name TEXT NOT NULL,
    marked_at TEXT DEFAULT CURRENT_TIMESTAMP,
    session_id TEXT NOT NULL
, status TEXT NOT NULL DEFAULT 'ABSENT', od TEXT DEFAULT 'NO');
CREATE TABLE IT_Attendance_2025_2029 (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    attendance_id TEXT NOT NULL,
    register_no TEXT NOT NULL,
    section TEXT NOT NULL,
    attendance_date TEXT NOT NULL,
    period INTEGER NOT NULL,
    subject_code TEXT NOT NULL,
    subject_name TEXT NOT NULL,
    marked_at TEXT DEFAULT CURRENT_TIMESTAMP,
    session_id TEXT NOT NULL
, status TEXT NOT NULL DEFAULT 'ABSENT', od TEXT DEFAULT 'NO');
CREATE TABLE staff (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    staff_id TEXT NOT NULL UNIQUE,
    staff_name TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    department TEXT NOT NULL,
    class_advisor TEXT,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    auth_user_id TEXT
, advisor_year INTEGER, advisor_section TEXT, advisor_batch TEXT);
CREATE TABLE auth_users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    auth_user_id TEXT NOT NULL UNIQUE,
    user_name TEXT NOT NULL UNIQUE,
    pwd_hash TEXT NOT NULL,
    role TEXT NOT NULL,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP
, email TEXT);
CREATE TABLE auth_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    token_hash TEXT NOT NULL,
    auth_user_id TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE attendance_session (
    session_id TEXT PRIMARY KEY,
    created_by TEXT NOT NULL,
    otp TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expire_at TEXT NOT NULL
, subject_code TEXT, subject_name TEXT, year INTEGER, section TEXT, period INTEGER, attendance_date TEXT, attendance_table TEXT, status TEXT NOT NULL DEFAULT 'ACTIVE', finalized_at TEXT, department TEXT NOT NULL DEFAULT 'IT', batch TEXT);
CREATE TABLE password_reset_tokens (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    auth_user_id TEXT NOT NULL,
    token_hash TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    used_at TEXT,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "subjects" (
    subject_id INTEGER PRIMARY KEY AUTOINCREMENT,
    subject_code TEXT NOT NULL UNIQUE,
    subject_name TEXT NOT NULL
);
CREATE TABLE CSE_Students_2024_2028 (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL UNIQUE,
    register_no TEXT NOT NULL UNIQUE,
    student_name TEXT NOT NULL,
    year INTEGER NOT NULL,
    section TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    auth_user_id TEXT
  , mentor_email TEXT);
CREATE TABLE CSE_Attendance_2024_2028 (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    attendance_id TEXT NOT NULL,
    register_no TEXT NOT NULL,
    section TEXT NOT NULL,
    attendance_date TEXT NOT NULL,
    period INTEGER NOT NULL,
    subject_code TEXT NOT NULL,
    subject_name TEXT NOT NULL,
    marked_at TEXT DEFAULT CURRENT_TIMESTAMP,
    session_id TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'ABSENT',
    od TEXT DEFAULT 'NO'
  );
CREATE TABLE academic_batches (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      department TEXT NOT NULL,
      batch TEXT NOT NULL,
      start_year INTEGER NOT NULL,
      end_year INTEGER NOT NULL,
      student_table TEXT NOT NULL,
      attendance_table TEXT NOT NULL,
      UNIQUE (department, batch));
CREATE TABLE hods (hod_id INTEGER PRIMARY KEY AUTOINCREMENT, hod_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, department TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE contest_coordinators (coordinator_id INTEGER PRIMARY KEY AUTOINCREMENT, coordinator_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, department TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE od_requests (
  
  od_request_id TEXT PRIMARY KEY,

  
  auth_user_id TEXT NOT NULL,
  student_table TEXT NOT NULL,
  student_id TEXT NOT NULL,
  student_name TEXT NOT NULL,
  student_email TEXT NOT NULL,
  department TEXT NOT NULL,
  batch TEXT NOT NULL,
  year INTEGER NOT NULL,
  section TEXT NOT NULL,

  
  mentor_email TEXT,

  
  
  od_days_gained_before INTEGER NOT NULL DEFAULT 0,

  
  submitted_date TEXT NOT NULL,
  od_days_requested INTEGER NOT NULL,
  od_dates TEXT NOT NULL,
  reason TEXT NOT NULL,

  
  status TEXT NOT NULL,

  
  mentor_decision TEXT,
  mentor_decided_by TEXT,
  mentor_decided_at TEXT,
  mentor_comment TEXT,

  coordinator_decision TEXT,
  coordinator_decided_by TEXT,
  coordinator_decided_at TEXT,
  coordinator_comment TEXT,

  advisor_decision TEXT,
  advisor_decided_by TEXT,
  advisor_decided_at TEXT,
  advisor_comment TEXT,

  hod_decision TEXT,
  hod_decided_by TEXT,
  hod_decided_at TEXT,
  hod_comment TEXT,

  
  rejected_at_stage TEXT,
  rejection_reason TEXT,
  rejected_at TEXT,

  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_auth_sessions_token_hash ON auth_sessions(token_hash);
CREATE INDEX idx_auth_sessions_auth_user_id ON auth_sessions(auth_user_id);
CREATE INDEX idx_auth_sessions_expires_at ON auth_sessions(expires_at);
CREATE INDEX idx_attendance_session_status
ON attendance_session(status);
CREATE INDEX idx_attendance_session_otp_status
ON attendance_session(otp, status);
CREATE INDEX idx_attendance_session_expire_at
ON attendance_session(expire_at);
CREATE INDEX idx_attendance_od ON IT_Attendance_2024_2028(od);
CREATE INDEX idx_attendance_od_2025 ON IT_Attendance_2025_2029(od);
