CREATE INDEX idx_students_auth_user_8_CSE_Students_2024_2028
       ON CSE_Students_2024_2028(auth_user_id);
CREATE INDEX idx_students_class_register_8_CSE_Students_2024_2028
       ON CSE_Students_2024_2028(year, section, register_no);
CREATE UNIQUE INDEX idx_attendance_session_register_28_IT_Students_2024_2028
       ON IT_Attendance_2024_2028(session_id, register_no);
